    where: { id: card.id },
    data: {
      listId: toList.id,
      boardId: toList.boardId,
      position: input.position,
    },
  });

  if (card.listId !== toList.id) {
    await logCardActivity(tx, {
      cardId: card.id,
      boardId: toList.boardId,
      action: "MOVED",
